function toBase64(bytes){const step=0x8000;let s='';for(let i=0;i<bytes.length;i+=step)s+=String.fromCharCode(...bytes.subarray(i,i+step));return btoa(s)}
function fromBase64(c){const v=atob(c),a=new Uint8Array(v.length);for(let i=0;i<v.length;i++)a[i]=v.charCodeAt(i);return a}
function isText(name){return /\.(json|md|txt|html?|css|js|ts|tsx|jsx|xml|svg|yaml|yml|csv|log|sql|dart|ini|toml|sh)$/i.test(name)}
function textPayload(bytes){return new TextDecoder('utf-8',{fatal:false}).decode(bytes)}
