function dbOpen(){return new Promise((resolve,reject)=>{try{const req=indexedDB.open('advogadoja-editor-v3-modelos-estados',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('state'))req.result.createObjectStore('state')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}catch(e){reject(e)}})}
async function persist(){try{const db=await dbOpen();await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(workspace,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();E('persistenceStatus').textContent='Salvo localmente neste navegador'}catch(err){E('persistenceStatus').textContent='Salvamento local indisponível · exporte backup';makeMessage('Persistência local bloqueada: exporte a árvore JSON ou o ZIP para guardar suas alterações.',true)}}
async function loadPersisted(){try{const db=await dbOpen();const value=await new Promise((resolve,reject)=>{const tx=db.transaction('state','readonly');const req=tx.objectStore('state').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();if(value&&value.format===DATA_FORMAT&&value.root?.kind==='folder')workspace=value;storageReady=true;E('persistenceStatus').textContent='Salvamento local disponível · V3'}catch(e){E('persistenceStatus').textContent='Sem armazenamento · exporte backup'}expanded.add(workspace.root.id);const first=workspace.root.children.find(n=>isDir(n));if(first)expanded.add(first.id);const screen=findScreens().find(s=>!inModel(s));if(screen){selectedId=screen.id;expandParents(screen.id)}else selectedId=workspace.root.id;render();makeMessage('Motor V3 pronto: 110 telas; composição, biblioteca, modelos e estados visuais.');}
function findScreens(){const out=[];(function walk(n){if(n.kind==='screen')out.push(n);if(isDir(n))n.children.forEach(walk)})(workspace.root);return out}
function promptForm(title,info,defaultValue='',opts={}){return new Promise(resolve=>{const d=E('formDialog'),input=E('dialogInput'),sel=E('dialogSelect'),lbl=E('dialogLabel2');E('dialogTitle').textContent=title;E('dialogInfo').textContent=info;E('dialogConfirm').textContent=opts.confirm||'Confirmar';input.value=defaultValue;input.placeholder=opts.placeholder||'Informe o nome';lbl.classList.toggle('hidden',!opts.select);sel.classList.toggle('hidden',!opts.select);sel.value='json';let done=false;const complete=v=>{if(done)return;done=true;d.removeEventListener('close',onClose);d.removeEventListener('cancel',onCancel);E('modalForm').removeEventListener('submit',onSubmit);resolve(v)};const onClose=()=>complete(null),onCancel=()=>complete(null),onSubmit=e=>{e.preventDefault();const sub=e.submitter;if(sub?.value==='cancel'){d.close();complete(null);return}const value=input.value.trim();if(!value){input.focus();return}d.close();complete(opts.select?{name:value,extension:sel.value}:value)};d.addEventListener('close',onClose);d.addEventListener('cancel',onCancel);E('modalForm').addEventListener('submit',onSubmit,{once:false});d.showModal();setTimeout(()=>{input.focus();input.select()},10)})}
async function addFolder(){if(!ensureSaved())return;const dst=targetFolder();if(!dst)return;const name=await promptForm('Nova pasta','Será criada dentro de '+filePath(dst));if(name===null)return;if(!nameOk(name)){toast('Nome inválido. Não use barras ou caracteres de controle.',true);return}if(dst.children.some(c=>c.name===name)){toast('Já existe um item com esse nome.',true);return}const n=node('folder',name);dst.children.push(n);selectedId=n.id;expandParents(n.id);markChanged();render();toast('Pasta criada: '+filePath(n))}
async function addDoc(){if(!ensureSaved())return;const dst=targetFolder();if(!dst)return;const v=await promptForm('Novo documento','Crie um JSON ou um documento de apoio nesta pasta.','documento',{select:true});if(v===null)return;let name=v.name;if(!/\.[a-z\d]+$/i.test(name))name+='.'+v.extension;if(!nameOk(name)){toast('Nome inválido.',true);return}if(dst.children.some(c=>c.name===name)){toast('Já existe um item com esse nome.',true);return}const n=node('file',name,{content:name.toLowerCase().endsWith('.json')?'{}':''});dst.children.push(n);selectedId=n.id;expandParents(n.id);markChanged();render();toast('Documento criado: '+filePath(n))}
async function addScreen(){if(!ensureSaved())return;let value=await promptForm('Criar tela','Informe o ID canônico (ex.: cliente.home.inicio). Os diretórios serão criados automaticamente.','',{placeholder:'dominio.modulo.tela'});if(value===null)return;const id=value.trim();if(!/^[\w-]+(?:\.[\w-]+)+$/.test(id)){toast('Use um ID composto por partes separadas por ponto; sem espaços ou barras.',true);return}let parent=activeTab==='modelo'?(modelRoot()||screensRoot()):screensRoot();const parts=id.split('.');for(const part of parts){let c=folderChild(parent,part);if(!c){c=node('folder',part);parent.children.push(c)}parent=c}if(parent.kind==='screen'){toast('Esta tela já existe: '+id,true);return}if(parent.children.length){toast('Este diretório já contém dados; para evitar sobrescrita, escolha outro ID.',true);return}parent.kind='screen';parent.children.push(node('file','meta.json',{content:formatJSON({schema:'advogadoja.tela',schemaVersion:'0.3.0'})}));for(const section of SECTION_ORDER){const fd=node('folder',section);if(section==='componentes')fd.children.push(node('folder','definicoes'));if(section==='identidade')fd.children.push(node('file','identidade.json',{content:formatJSON({id,tipo:'tela',namespace:parts[0],nome:parts[parts.length-1]})}));parent.children.push(fd)}selectedId=parent.id;expandParents(parent.id);markChanged();render();toast('Tela criada: '+id)}
async function rename(){if(!ensureSaved())return;const x=selected(),n=x.node;if(!x.parent)return;const value=await promptForm('Renomear item','A renomeação não altera referências dentro dos JSONs.',n.name);if(value===null)return;const name=value.trim();if(!nameOk(name)){toast('Nome inválido.',true);return}if(x.parent.children.some(c=>c!==n&&c.name===name)){toast('Já existe item com esse nome.',true);return}n.name=name;markChanged();render();toast('Item renomeado. Confira as referências, se aplicável.')}
function del(){if(!ensureSaved())return;const x=selected();if(!x.parent)return;if(!confirm('Excluir permanentemente '+filePath(x.node)+' e todo seu conteúdo? Esta ação afeta a árvore aberta; pode ser revertida importando um backup.'))return;const i=x.parent.children.findIndex(c=>c.id===x.node.id);if(i>=0)x.parent.children.splice(i,1);selectedId=x.parent.id;markChanged();render();toast('Item excluído.')}
function pickFolderForUpload(){return targetFolder()||workspace.root}
async function importFilesInto(folder,files){let imported=0;for(const f of files){if(!f||!nameOk(f.name))continue;const bytes=new Uint8Array(await f.arrayBuffer());const item=node('file',f.name,isText(f.name)?{encoding:'text',content:textPayload(bytes)}:{encoding:'base64',content:toBase64(bytes)});const old=folder.children.find(c=>c.name===f.name);if(old){if(!confirm('Já existe '+f.name+' em '+filePath(folder)+'. Substituir?'))continue;folder.children.splice(folder.children.indexOf(old),1)}folder.children.push(item);imported++}if(imported){markChanged();toast(imported+' arquivo(s) importado(s) em '+filePath(folder))}return imported}
function directChild(parent,name,kind='folder'){let v=parent.children.find(c=>c.name===name);if(v){if(!isDir(v))throw Error(name+' conflita com um documento');return v}v=node(kind,name);parent.children.push(v);return v}
function canonicalIdOf(contract){return contract?.tela?.identidade?.id}
function importContract(data,filename){const id=canonicalIdOf(data);if(typeof id!=='string'||!/^[\w-]+(?:\.[\w-]+)+$/.test(id))throw Error('Contrato '+filename+': tela.identidade.id ausente/inválido.');if(!data.componentes||typeof data.componentes!=='object'||Array.isArray(data.componentes))throw Error('Contrato '+filename+': o objeto componentes da raiz é necessário.');let parent=workspace.root;for(const segment of id.split('.'))parent=directChild(parent,segment);if(parent.kind==='screen'&&parent.children.length&&!confirm('A tela '+id+' já existe. Substituir seu conteúdo modular?'))return false;parent.kind='screen';parent.children=[];const t=data.tela,meta={};for(const [k,v] of Object.entries(t))if(k==='schema'||k==='schemaVersion'||!SECTION_ORDER.includes(k))meta[k]=v;parent.children.push(node('file','meta.json',{content:formatJSON(meta)}));for(const s of SECTION_ORDER){const dir=node('folder',s);parent.children.push(dir);if(s==='componentes'){if(Object.prototype.hasOwnProperty.call(t,s))dir.children.push(node('file','instancias.json',{content:formatJSON(t[s])}));const defs=node('folder','definicoes');dir.children.push(defs);for(const [key,comp] of Object.entries(data.componentes)){if(!nameOk(key))throw Error('Chave inválida no componente '+key);const unit=node('folder',key);unit.children.push(node('file','componente.json',{content:formatJSON(comp)}));defs.children.push(unit)}}else if(Object.prototype.hasOwnProperty.call(t,s))dir.children.push(node('file',s+'.json',{content:formatJSON(t[s])}))}selectedId=parent.id;expandParents(parent.id);return true}
async function handleJsonInput(files){if(!ensureSaved())return;let done=0;for(const f of files){try{const data=JSON.parse(await f.text());if(data?.format===DATA_FORMAT&&data.root){if(!validateTree(data))throw Error('Arquivo de árvore inválido.');if(!confirm('Substituir a árvore atual por '+f.name+'? Exporte um backup antes, se necessário.'))continue;workspace=data;selectedId=workspace.root.id;expanded=new Set([workspace.root.id]);done++;}
else if(data?.tela&&data?.componentes){if(importContract(data,f.name))done++}
else{const dir=pickFolderForUpload();await importFilesInto(dir,[f]);done++}}catch(e){toast(f.name+': '+e.message,true)}}if(done){dirty=false;markChanged();render();toast(done+' importação(ões) JSON concluída(s).')}}
function validateTree(value){if(!value||value.format!==DATA_FORMAT||!value.root||!isDir(value.root))return false;const ids=new Set();let total=0;function walk(n,depth){if(depth>45||++total>50000||!nameOk(n.name)||typeof n.id!=='string'||ids.has(n.id))throw Error('Nó inválido, repetido ou árvore grande demais.');ids.add(n.id);if(isDir(n)){if(!Array.isArray(n.children))throw Error('Pasta sem children[]');n.children.forEach(c=>walk(c,depth+1))}else if(n.kind==='file'){if(typeof n.content!=='string'||!['text','base64'].includes(n.encoding))throw Error('Documento inválido')}else throw Error('Tipo de nó inválido')}try{walk(value.root,0);return true}catch(e){return false}}
function assembleScreen(screen){if(!screen||screen.kind!=='screen')throw Error('Selecione uma tela.');const meta=fileChild(screen,'meta.json');if(!meta)throw Error('meta.json não encontrado em '+filePath(screen));let t;try{t=JSON.parse(meta.content)}catch(e){throw Error('meta.json inválido: '+e.message)}if(!t||typeof t!=='object'||Array.isArray(t))throw Error('meta.json deve conter um objeto JSON.');if(!t.schema||!t.schemaVersion)throw Error('meta.json requer schema e schemaVersion.');const out={tela:{...t},componentes:{}};for(const section of SECTION_ORDER){const fld=folderChild(screen,section);if(!fld)continue;if(section==='componentes'){const instances=fileChild(fld,'instancias.json');if(instances){try{out.tela.componentes=JSON.parse(instances.content)}catch(e){throw Error('componentes/instancias.json inválido: '+e.message)}}const defs=folderChild(fld,'definicoes');if(defs)for(const entry of defs.children.filter(isDir)){const f=fileChild(entry,'componente.json');if(!f)continue;try{out.componentes[entry.name]=JSON.parse(f.content)}catch(e){throw Error('Componente '+entry.name+': '+e.message)}}}else{const filename=section+'.json',f=fileChild(fld,filename);if(f){try{out.tela[section]=JSON.parse(f.content)}catch(e){throw Error(section+'/'+filename+': '+e.message)}}}}const id=out.tela.identidade?.id;if(typeof id!=='string'||!id.trim())throw Error('identidade/identidade.json precisa declarar tela.identidade.id.');return out}
function assembleCurrent(){if(!ensureSaved())return;try{const screen=ancestorScreen(selectedId)||visibleScreens()[0];if(!screen)throw Error('Nenhuma tela encontrada.');const assembled=assembleScreen(screen);const name=(assembled.tela.identidade.id||'tela').replace(/[^\w.-]/g,'_');blobDownload(name+'.documento.json',formatJSON(assembled),'application/json');toast('Contrato montado: '+assembled.tela.identidade.id+'. O arquivo contém tela + componentes.')}catch(e){toast('Montagem não concluída: '+e.message,true)}}
function exportTree(){if(!ensureSaved())return;const data={...workspace,exportedAt:new Date().toISOString()};blobDownload('AdvogadoJa_arvore_modular.json',formatJSON(data),'application/json');toast('Árvore modular exportada em JSON.')}
function gatherFiles(n,base=''){let res=[];function walk(x,path){if(x.kind==='file'){res.push({name:path,bytes:asTextFile(x)});return}res.push({name:path+'/',bytes:new Uint8Array(0),isDir:true});for(const c of x.children)walk(c,path?path+'/'+c.name:c.name)}walk(n,base);return res}
const CRC_TABLE=new Uint32Array(256);for(let i=0;i<256;i++){let c=i;for(let j=0;j<8;j++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;CRC_TABLE[i]=c>>>0}
