function makeZIP(files){const enc=new TextEncoder,locals=[],central=[];let offset=0;const now=new Date();const dosTime=((now.getHours()&31)<<11)|((now.getMinutes()&63)<<5)|((now.getSeconds()/2)&31),dosDate=(((now.getFullYear()-1980)&127)<<9)|(((now.getMonth()+1)&15)<<5)|(now.getDate()&31);for(const f of files){const name=enc.encode(f.name),payload=f.bytes,crc=crc32(payload);if(name.length>65535||payload.length>0xffffffff)throw Error('Arquivo excede limite do ZIP.');const local=new Uint8Array(30+name.length),v=new DataView(local.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(8,0,true);v.setUint16(10,dosTime,true);v.setUint16(12,dosDate,true);v.setUint32(14,crc,true);v.setUint32(18,payload.length,true);v.setUint32(22,payload.length,true);v.setUint16(26,name.length,true);local.set(name,30);locals.push(local,payload);const cen=new Uint8Array(46+name.length),cv=new DataView(cen.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(10,0,true);cv.setUint16(12,dosTime,true);cv.setUint16(14,dosDate,true);cv.setUint32(16,crc,true);cv.setUint32(20,payload.length,true);cv.setUint32(24,payload.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);if(f.isDir)cv.setUint32(38,16<<16,true);cen.set(name,46);central.push(cen);offset+=local.length+payload.length}const cdSize=central.reduce((x,v)=>x+v.length,0);if(files.length>65535||offset>0xffffffff||cdSize>0xffffffff)throw Error('ZIP grande demais para formato básico.');const end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,cdSize,true);e.setUint32(16,offset,true);return new Blob([...locals,...central,end],{type:'application/zip'})}
function exportZip(){if(!ensureSaved())return;try{const files=gatherFiles(workspace.root,workspace.root.name);blobDownload('AdvogadoJa_telas_modulares.zip',makeZIP(files));toast('ZIP modular exportado com telas reais, READMEs e Tela-Modelo: '+files.length+' entradas.')}catch(e){toast('Erro exportando ZIP: '+e.message,true)}}
function exportContracts(){if(!ensureSaved())return;try{const arr=findScreens().filter(s=>!inModel(s));const files=arr.map(s=>{const a=assembleScreen(s),id=a.tela.identidade.id;return{name:'contratos/'+id+'.json',bytes:new TextEncoder().encode(formatJSON(a))}});blobDownload('AdvogadoJa_contratos_montados.zip',makeZIP(files));toast('ZIP exportado com '+files.length+' contratos completos.')}catch(e){toast('Erro montando contratos: '+e.message,true)}}
function downloadSelected(){if(!ensureSaved())return;const n=selected().node;if(n.kind==='file'){blobDownload(n.name,asTextFile(n));toast('Documento exportado: '+n.name)}else{try{if(n.kind==='screen'){const d=assembleScreen(n),id=d.tela.identidade.id;blobDownload(id+'.documento.json',formatJSON(d),'application/json');toast('Contrato montado e exportado.')}else{const arr=gatherFiles(n,filePath(n));blobDownload(n.name+'_pasta.zip',makeZIP(arr));toast('Pasta exportada em ZIP.')}}catch(e){toast(e.message,true)}}}
async function deflateRaw(bytes){if(typeof DecompressionStream==='undefined')throw Error('Seu navegador não oferece descompressão ZIP. Importe um ZIP sem compressão ou o JSON da árvore.');let ds;try{ds=new DecompressionStream('deflate-raw')}catch(e){throw Error('Este navegador não lê ZIP com DEFLATE-raw. Use ZIP sem compressão ou importe contratos JSON.')}const stream=new Blob([bytes]).stream().pipeThrough(ds);return new Uint8Array(await new Response(stream).arrayBuffer())}
async function readZIP(buffer){const bytes=new Uint8Array(buffer),v=new DataView(buffer),dec=new TextDecoder('utf-8');let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--){if(v.getUint32(i,true)===0x06054b50){end=i;break}}if(end<0)throw Error('Cabeçalho de ZIP não encontrado.');const entries=v.getUint16(end+10,true),cdOffset=v.getUint32(end+16,true);if(entries>40000)throw Error('ZIP contém documentos demais.');let pos=cdOffset,total=0;const result=[];for(let i=0;i<entries;i++){if(pos+46>bytes.length||v.getUint32(pos,true)!==0x02014b50)throw Error('Diretório ZIP inválido.');const method=v.getUint16(pos+10,true),compSize=v.getUint32(pos+20,true),rawSize=v.getUint32(pos+24,true),nameLen=v.getUint16(pos+28,true),extraLen=v.getUint16(pos+30,true),commentLen=v.getUint16(pos+32,true),localOffset=v.getUint32(pos+42,true);const name=dec.decode(bytes.subarray(pos+46,pos+46+nameLen)).replace(/\\/g,'/');pos+=46+nameLen+extraLen+commentLen;const isDirEntry=name.endsWith('/');if(!name||name.startsWith('/')||name.split('/').some(p=>p==='..'||p==='.')||name.includes(':')){throw Error('Caminho inseguro no ZIP: '+name)}if(rawSize>80_000_000||total+rawSize>260_000_000)throw Error('ZIP excede o limite de segurança de importação.');total+=rawSize;if(isDirEntry){result.push({name,bytes:new Uint8Array(0),isDir:true});continue}if(localOffset+30>bytes.length||v.getUint32(localOffset,true)!==0x04034b50)throw Error('Entrada ZIP corrompida: '+name);const lName=v.getUint16(localOffset+26,true),lExtra=v.getUint16(localOffset+28,true),start=localOffset+30+lName+lExtra;if(start+compSize>bytes.length)throw Error('Arquivo ZIP truncado: '+name);const packed=bytes.subarray(start,start+compSize);let payload;if(method===0)payload=packed.slice();else if(method===8)payload=await deflateRaw(packed);else throw Error('Compactação ZIP não suportada (método '+method+'): '+name);if(payload.length!==rawSize)throw Error('Tamanho inconsistente em '+name);result.push({name,bytes:payload})}return result}
function addZipEntries(files){let first=files.find(f=>f.name.split('/').includes('telas'));const hasTelas=!!first;const dst=hasTelas?workspace.root:pickFolderForUpload();let added=0;for(const f of files){let parts=f.name.split('/').filter(Boolean);if(hasTelas){let idx=parts.indexOf('telas');if(idx<0)continue;parts=parts.slice(idx+1)}if(!parts.length)continue;let parent=dst;if(f.isDir){for(const part of parts){if(!nameOk(part))throw Error('Pasta inválida em ZIP: '+part);parent=directChild(parent,part)}continue}for(const part of parts.slice(0,-1)){if(!nameOk(part))throw Error('Pasta inválida em ZIP: '+part);parent=directChild(parent,part)}const name=parts.at(-1);if(!nameOk(name))throw Error('Nome inválido em ZIP');const content=isText(name)?{encoding:'text',content:textPayload(f.bytes)}:{encoding:'base64',content:toBase64(f.bytes)};const existing=parent.children.find(c=>c.name===name);if(existing){if(existing.kind!=='file')throw Error('Documento conflita com pasta: '+name);parent.children.splice(parent.children.indexOf(existing),1)}parent.children.push(node('file',name,content));added++}
if(hasTelas){(function visit(n){if(isDir(n)){const hasMeta=!!fileChild(n,'meta.json'),identity=folderChild(n,'identidade');if(hasMeta&&fileChild(identity,'identidade.json'))n.kind='screen';n.children.forEach(visit)}})(workspace.root)}return added}
async function importZip(f){if(!ensureSaved())return;try{let entries=await readZIP(await f.arrayBuffer());if(!entries.length)throw Error('ZIP está vazio.');if(!confirm('Importar '+entries.length+' documentos do ZIP? Arquivos de mesmo caminho serão substituídos.'))return;const count=addZipEntries(entries);markChanged();render();toast('ZIP importado: '+count+' arquivos.')}catch(e){toast('Falha na importação ZIP: '+e.message,true)}}

