function detectScreens(n=workspace.root){if(!isDir(n))return;const identity=folderChild(n,'identidade'),structure=folderChild(n,'estrutura'),classif=folderChild(n,'classificacao');if(identity&&structure&&classif&&fileChild(folderChild(n,'componentes'),'instancias.json')&&fileChild(identity,'identidade.json')&&fileChild(structure,'estrutura.json'))n.kind='screen';for(const c of n.children)if(isDir(c))detectScreens(c)}
function loadJson(n,label,required=false){if(!n){if(required)throw Error('Arquivo ausente: '+label);return null}try{return JSON.parse(n.content)}catch(e){throw Error('JSON inválido ('+label+'): '+e.message)}}
function assembleScreen(screen){if(!screen||screen.kind!=='screen')throw Error('Selecione uma tela.');const meta=fileChild(screen,'meta.json');const t=meta?loadJson(meta,'meta.json'):{};const out={tela:{...t},componentes:{}};for(const section of SECTION_ORDER){const fld=folderChild(screen,section);if(!fld)continue;if(section==='componentes'){
 const ins=fileChild(fld,'instancias.json');if(ins)out.tela.componentes=loadJson(ins,'instancias.json');
 const defs=folderChild(fld,'definicoes');for(const d of defs?.children||[]){if(!isDir(d))continue;const full=fileChild(d,'componente.json');if(full)out.componentes[d.name]=loadJson(full,d.name+'/componente.json');else{
 const result={};for(const p of ['identidade','classificacao','estrutura']){const f=fileChild(folderChild(d,p),p+'.json');if(f)result[p]=loadJson(f,d.name+'/'+p)}if(Object.keys(result).length)out.componentes[d.name]=result;
 }}
 }else{const f=fileChild(fld,section+'.json');if(f)out.tela[section]=loadJson(f,section+'.json')}}
 if(typeof out.tela.identidade?.id!=='string'||!out.tela.identidade.id.trim())throw Error('identidade/identidade.json precisa declarar o ID');return out;}
