 E('guideDesc').textContent=library?'Edite identidade, classificação, estrutura, estados visuais e modelos. A mesma definição central é consumida por referências de todas as telas.':model?'Exemplo documental preservado; não substitui os contratos reais.':'A composição em estrutura.json seleciona, posiciona e configura cada componente. Os destinos permanecem em navegacao.json.';
 E('guideReadme').hidden=library;E('guideReadme').textContent=model?'▤ README do modelo':'▤ README da Home';
 E('guideMatrix').hidden=!model;E('guidePreview').hidden=!model;
